import Foundation

// Ein Textblock einer Terms-Sektion, in allen acht Sprachen — analog zu
// HandbuchBlock/HandbuchSection, aber bewusst als eigener Typ (keine
// Kopplung an den Handbuch-Inhalt, andere Domäne). `paragraph` erlaubt
// einfache Markdown-Hervorhebung (**fett**), gerendert per
// AttributedString(markdown:) in TermsView.
enum TermsBlock {
    case heading(de: String, en: String, es: String, pt: String, fr: String, it: String, nl: String, pl: String)
    case paragraph(de: String, en: String, es: String, pt: String, fr: String, it: String, nl: String, pl: String)
    /// Anbieter-Adressblock (§1.2) — eigene Darstellung als Karte statt Fließtext.
    case providerBlock
}

struct TermsSection: Identifiable {
    let id = UUID()
    let titleDE: String
    let titleEN: String
    let titleES: String
    let titlePT: String
    let titleFR: String
    let titleIT: String
    let titleNL: String
    let titlePL: String
    let blocks: [TermsBlock]
}

